def retry(fn, attempts=3, base=100, sleep=time.sleep):
    """Call fn() with exponential backoff; raise on exhaustion."""
    last = None
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as exc:  # noqa: BLE001
